insert into public.services (title,slug,category,image_url,duration,inclusions,status,kicker,short_description,description,content,suitable_for,benefits,sort_order,robots_index) select 'Dog Training','dog-training','Dog Training','/assets/real/obedience.webp','Plan confirmed after consultation','["Puppy and obedience foundations","Leash and recall skills","Behaviour-based programs"]','published','Professional training for everyday life','Personalised dog training for puppies and adult dogs, from household manners and obedience to leash skills and complex behaviour support.','Personalised dog training for puppies and adult dogs, from household manners and obedience to leash skills and complex behaviour support.','[{"kind":"paragraph","text":"Effective dog training is about more than teaching commands. It helps your dog understand what is expected while giving you a reliable way to guide them at home and outdoors."},{"kind":"paragraph","text":"Every plan considers age, breed, learning history, home routine and the situations where behaviour becomes difficult. Skills are taught progressively and practised in the real environments where you need them."}]','Puppies and adult dogs','["Clear everyday communication","Positive, practical routines","Pet-parent coaching"]',0,true where not exists (select 1 from public.services where slug='dog-training');
insert into public.services (title,slug,category,image_url,duration,inclusions,status,kicker,short_description,description,content,suitable_for,benefits,sort_order,robots_index) select 'Cat Training','cat-training','Cat Training','/assets/real/cat-session.webp','Plan confirmed after consultation','["Litter and home routines","Target and recall foundations","Scratching and handling guidance"]','published','Positive guidance for curious cats','Feline-friendly training for litter habits, scratching, handling, routines and enrichment—without force or intimidation.','Feline-friendly training for litter habits, scratching, handling, routines and enrichment—without force or intimidation.','[{"kind":"paragraph","text":"Cats learn through association, choice and rewards. A thoughtful plan can improve litter habits, reduce unwanted scratching and make everyday handling easier."},{"kind":"paragraph","text":"Sessions focus on the environment as much as the cat, helping pet parents provide suitable outlets for climbing, play, rest and natural behaviour."}]','Kittens and adult cats','["Better home habits","Handling confidence","Healthy enrichment"]',1,true where not exists (select 1 from public.services where slug='cat-training');
insert into public.services (title,slug,category,image_url,duration,inclusions,status,kicker,short_description,description,content,suitable_for,benefits,sort_order,robots_index) select 'Pet Grooming','grooming','Grooming','/assets/real/puppy-focus.webp','Depends on coat and service','["Bathing and drying","Brushing and de-shedding","Nail and ear care"]','published','Comfort, hygiene and coat care','Professional bathing, brushing, trimming and hygiene care for dogs and cats, with convenient at-home options where available.','Professional bathing, brushing, trimming and hygiene care for dogs and cats, with convenient at-home options where available.','[{"kind":"paragraph","text":"Regular grooming supports skin health, coat condition and comfort. It also creates an opportunity to notice changes that may need veterinary attention."},{"kind":"paragraph","text":"Service scope depends on coat, size, condition and handling needs. The final recommendation is confirmed before the appointment."}]','Dogs and cats','["Coat and skin upkeep","Nail, ear and hygiene care","Low-stress handling"]',2,true where not exists (select 1 from public.services where slug='grooming');
insert into public.services (title,slug,category,image_url,duration,inclusions,status,kicker,short_description,description,content,suitable_for,benefits,sort_order,robots_index) select 'Dog Walking','dog-walking','Dog Walking','/assets/real/obedience.webp','Duration selected at booking','["Individual walking plan","Basic leash reinforcement","Visit update"]','published','Healthy movement and calmer routines','Reliable dog walking that supports physical activity, mental stimulation and better neighbourhood manners.','Reliable dog walking that supports physical activity, mental stimulation and better neighbourhood manners.','[{"kind":"paragraph","text":"A good walk is more than exercise. Sniffing, exploring and calmly navigating the neighbourhood contribute to physical health and emotional wellbeing."},{"kind":"paragraph","text":"Walking plans consider age, fitness, weather, route safety and existing leash skills. Training support can be added when pulling or reactivity makes walks difficult."}]','Dogs needing consistent exercise','["Appropriate daily activity","Mental stimulation","Calmer walking routines"]',3,true where not exists (select 1 from public.services where slug='dog-walking');
