insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Puppy Training','puppy-training','Dog Training','/assets/real/puppy-focus.webp','(12 Sessions), 1 Month - (Food & Stay Included)','(12 Sessions), 1 Month - (Food & Stay Included)',20500,17500,'[]','published','Dog Training','Give your puppy the perfect start with Puppy Training at Farmhouse by Pawrexio. Our farmhouse training program offers a peaceful, open, and safe environment where puppies can learn essential skills, build confidence, and develop p','[{"kind":"paragraph","text":"Give your puppy the perfect start with Puppy Training at Farmhouse by Pawrexio. Our farmhouse training program offers a peaceful, open, and safe environment where puppies can learn essential skills, build confidence, and develop positive behavior through fun and structured training sessions."},{"kind":"paragraph","text":"This program is specially designed for young puppies to improve obedience, socialization, discipline, and overall behavior while enjoying outdoor activities and supervised interaction in a stress-free setting."},{"kind":"paragraph","text":"Potty / Pee Training"},{"kind":"paragraph","text":"Basic Social Etiquettes"},{"kind":"paragraph","text":"Puppy Biting Correction"},{"kind":"paragraph","text":"Instruction - Sit, Stay, Shake Hand Walking - Come, Go"}]',6,true where not exists (select 1 from public.training_programs where slug='puppy-training');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Intermediate Dog Training','intermediate-dog-training','Dog Training','/assets/real/heelwork.webp','(36 Sessions), 3 Months','(36 Sessions), 3 Months',43500,37500,'["Leash Walking - Heel Walk, Turn, Slow Walk, Fast Walk","Lower Acrobat Module - Crawl, Rollover, Lie Down, Sleep (Play dead)","Advanced Potty / Pee Training","Basic Social Etiquettes - Don''t Jump, Don''t Pull, Boundaries in House","Biting/Mouthing Correction","7 Basic Commands - Sit, Down, Stay, Hi5, Handshake, Come, Go","5 No Commands - No, Don''t Jump, Don''t bark, don’t Pull, Don''t Eat"]','published','Dog Training','Take your dog’s obedience and behavior skills to the next level with the Intermediate Training at Farmhouse Program by Pawrexio. Conducted in a peaceful and spacious farmhouse environment, this advanced training program is designe','[{"kind":"paragraph","text":"Take your dog’s obedience and behavior skills to the next level with the Intermediate Training at Farmhouse Program by Pawrexio. Conducted in a peaceful and spacious farmhouse environment, this advanced training program is designed to improve discipline, social behavior, leash control, and fun acrobatic skills through structured professional sessions."},{"kind":"paragraph","text":"Our experienced trainers use positive reinforcement techniques to help dogs become confident, obedient, and well-mannered companions while enjoying outdoor learning and activity-based training"},{"kind":"list","text":"Leash Walking - Heel Walk, Turn, Slow Walk, Fast Walk"},{"kind":"list","text":"Lower Acrobat Module - Crawl, Rollover, Lie Down, Sleep (Play dead)"},{"kind":"list","text":"Advanced Potty / Pee Training"},{"kind":"list","text":"Basic Social Etiquettes - Don''t Jump, Don''t Pull, Boundaries in House"},{"kind":"list","text":"Biting/Mouthing Correction"},{"kind":"list","text":"7 Basic Commands - Sit, Down, Stay, Hi5, Handshake, Come, Go"},{"kind":"list","text":"5 No Commands - No, Don''t Jump, Don''t bark, don’t Pull, Don''t Eat"}]',7,true where not exists (select 1 from public.training_programs where slug='intermediate-dog-training');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Leash Training For Dogs','leash-training-for-dogs','Dog Training','/assets/real/walking.webp','Making Daily Walks Safer','Making Daily Walks Safer',null,null,'[]','published','Dog Training','At Pawrexio , our Leash Training for Dogs program helps your pet learn to walk calmly and confidently by your side without pulling, lunging, or getting distracted. Whether you have a playful puppy or an adult dog that struggles du','[{"kind":"paragraph","text":"At Pawrexio , our Leash Training for Dogs program helps your pet learn to walk calmly and confidently by your side without pulling, lunging, or getting distracted. Whether you have a playful puppy or an adult dog that struggles during walks, our experienced trainers use positive reinforcement techniques to teach proper leash manners in a safe and stress-free environment."},{"kind":"paragraph","text":"Our training focuses on improving your dog''s walking behaviour, responsiveness to commands, and confidence in different surroundings. We gradually introduce real-life situations such as busy streets, parks, and residential areas so your dog learns to stay calm and obedient during daily walks. With regular practice and personalised guidance, leash training strengthens the bond between you and your pet while making every walk more enjoyable."},{"kind":"paragraph","text":"Pawrexio provides personalised home-visit leash training sessions designed around your dog''s age, breed, temperament, and learning pace. Our goal is to help pet parents enjoy safe, comfortable, and hassle-free walks while building lifelong good habits for their furry companions."}]',8,true where not exists (select 1 from public.training_programs where slug='leash-training-for-dogs');
