insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Bath & Brush','bath--brush','Grooming','/assets/real/companions.webp','Available for Cats & Dogs','Available for Cats & Dogs',1069,749,'[]','published','Grooming','Our Bath & Brush service for Cats and Dogs is designed to keep your pet clean, comfortable, and looking their best. Whether it’s a playful pup or a finicky feline, our gentle grooming approach ensures a stress-free experience usin','[{"kind":"paragraph","text":"Our Bath & Brush service for Cats and Dogs is designed to keep your pet clean, comfortable, and looking their best. Whether it’s a playful pup or a finicky feline, our gentle grooming approach ensures a stress-free experience using pet-safe shampoos and tools. Each session includes a thorough bath, gentle brushing to remove loose fur and prevent matting, and a quick check for any skin or coat issues. Perfect for regular maintenance or a refreshing treat, this service helps your pet stay fresh, healthy, and happy."}]',16,true where not exists (select 1 from public.training_programs where slug='bath--brush');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Tick Treatment With Bath & Brush','tick-treatment-with-bath-brush','Grooming','/assets/real/home-training.webp','Available for Cats & Dogs','Available for Cats & Dogs',1579,1150,'[]','published','Grooming','Our Tick Treatment with Bath & Brush service offers a complete grooming and parasite control solution to keep your dog clean, comfortable, and protected. This treatment includes a thorough bath using vet-approved anti-tick shampoo','[{"kind":"paragraph","text":"Our Tick Treatment with Bath & Brush service offers a complete grooming and parasite control solution to keep your dog clean, comfortable, and protected. This treatment includes a thorough bath using vet-approved anti-tick shampoo, followed by careful brushing to remove loose hair and stimulate healthy skin. Designed to eliminate ticks and soothe irritated skin, the session not only helps prevent infestations but also leaves your dog feeling fresh, relaxed, and pampered. Ideal as part of a regular grooming routine or whenever your dog needs extra care after outdoor activities."}]',17,true where not exists (select 1 from public.training_programs where slug='tick-treatment-with-bath-brush');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Haircut & Styling','haircut-styling','Grooming','/assets/real/attention.webp','Available for Cats & Dogs','Available for Cats & Dogs',1629,1179,'[]','published','Grooming','Our Haircut & Styling service offers your dog a professional grooming experience, tailored to their breed, coat type, and personality. Whether your furry friend needs a simple trim or a full grooming session, our experienced groom','[{"kind":"paragraph","text":"Our Haircut & Styling service offers your dog a professional grooming experience, tailored to their breed, coat type, and personality. Whether your furry friend needs a simple trim or a full grooming session, our experienced groomers ensure they look and feel their best. Using high-quality products and gentle techniques, we provide everything from stylish cuts to soothing baths, nail trimming, and ear cleaning. With a focus on comfort and safety, your dog will leave feeling refreshed, confident, and looking fabulous—ready to turn heads wherever they go!"}]',18,true where not exists (select 1 from public.training_programs where slug='haircut-styling');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Bath, Haircut & Styling','bath-haircut-styling','Grooming','/assets/real/indoor-training.webp','Available for Cats & Dogs','Available for Cats & Dogs',3298,1649,'[]','published','Grooming','Our Bath, Haircut & Styling service is designed to keep your cats and dogs looking and feeling their best. Whether it''s a soothing bath, a stylish haircut, or a complete grooming session, our experienced groomers provide gentle an','[{"kind":"paragraph","text":"Our Bath, Haircut & Styling service is designed to keep your cats and dogs looking and feeling their best. Whether it''s a soothing bath, a stylish haircut, or a complete grooming session, our experienced groomers provide gentle and professional care tailored to your pet''s needs. We use high-quality, pet-friendly products to ensure their coat is clean, shiny, and healthy, while also offering stylish cuts that enhance their natural beauty. From short-haired to long-haired breeds, we ensure your furry friend leaves feeling pampered, refreshed, and ready to show off their new look!"}]',19,true where not exists (select 1 from public.training_programs where slug='bath-haircut-styling');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Massage, Bath, Full Haircut & Styling','massage-bath-full-haircut-styling','Grooming','/assets/real/companions.webp','Available for Cats & Dogs','Available for Cats & Dogs',2699,1899,'[]','published','Grooming','Pamper your furry companion with our Massage, Bath, Full Haircut & Styling services, available for both cats and dogs. Our expert groomers use gentle, pet-friendly products to ensure your pet enjoys a soothing, relaxing experience','[{"kind":"paragraph","text":"Pamper your furry companion with our Massage, Bath, Full Haircut & Styling services, available for both cats and dogs. Our expert groomers use gentle, pet-friendly products to ensure your pet enjoys a soothing, relaxing experience while looking their best. From a rejuvenating massage to relieve stress and tension, to a refreshing bath that leaves them smelling fresh, we offer a complete grooming experience. Our professional grooming team also provides precise haircuts and stylish trims, tailored to your pet’s breed and personality. Treat your pet to a spa day, enhancing both their appearance and well-being!"}]',20,true where not exists (select 1 from public.training_programs where slug='massage-bath-full-haircut-styling');
insert into public.training_programs (title,slug,category,image_url,duration,session_count,price_from,sale_price,inclusions,status,level,summary,content,sort_order,robots_index) select 'Professional Dog Walker','proffesional-dog-walker','Dog Walking','/assets/real/walking.webp','Per Month (Twice a Day)','Per Month (Twice a Day)',9600,7999,'[]','published','Dog Walking','Our Per Month Basic Dog Walking Package offers twice-daily walks designed to keep your dog physically active, mentally stimulated, and emotionally balanced. Perfect for pet parents with busy schedules, this service ensures your do','[{"kind":"paragraph","text":"Our Per Month Basic Dog Walking Package offers twice-daily walks designed to keep your dog physically active, mentally stimulated, and emotionally balanced. Perfect for pet parents with busy schedules, this service ensures your dog enjoys consistent morning and evening walks, promoting better health, behavior, and routine. Each walk is led by a caring, trained professional who prioritizes your dog’s safety, comfort, and happiness. Whether it’s a brisk exercise session or a relaxed stroll, we tailor each walk to suit your dog’s unique needs, helping them stay happy, healthy, and well-adjusted."}]',21,true where not exists (select 1 from public.training_programs where slug='proffesional-dog-walker');
